.checkbox-label {
    line-height: 1.5;
    font-size: 16px;
    color: #333;
}

.checkbox-label a {
    color: #667eea;
    text-decoration: none;
    font-weight: 500;
    border-bottom: 1px solid transparent;
    transition: border-color 0.2s;
}

.checkbox-label a:hover,
.checkbox-label a:focus {
    border-bottom-color: #667eea;
    outline: none;
}

.checkbox-label a:focus {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

